private fun minuteLabel(n:Int)="%02d:%02d".format(n/60,n%60)
private fun minuteValue(s:String):Int{val p=s.split(':');require(p.size==2);val h=p[0].toInt();val m=p[1].toInt();require(h in 0..24&&m in 0..59&&(h!=24||m==0));return h*60+m}
